<?php require __DIR__.'/includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT h.*,COALESCE(AVG(rv.note),0) note,COUNT(DISTINCT rv.id) avis FROM hotels h LEFT JOIN reviews rv ON rv.hotel_id=h.id WHERE h.id=? AND h.actif=1 GROUP BY h.id');$s->execute([$id]);$hotel=$s->fetch();if(!$hotel){http_response_code(404);exit('Hôtel introuvable.');}$rooms=$pdo->prepare('SELECT * FROM rooms WHERE hotel_id=? AND disponible=1 ORDER BY prix_nuit');$rooms->execute([$id]);$title=$hotel['nom'];$hero=$hotel['image_principale']?:'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1400&q=85';require __DIR__.'/includes/header.php';?>
